import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({ name: '', subject: 'O/L - Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });

  const fetchTeachers = () => {
    axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
  };

  useEffect(() => { fetchTeachers(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/add-teacher', formData).then(res => {
      if(res.data.status === "Success") {
        fetchTeachers();
        setShowForm(false);
        setFormData({ name: '', subject: 'O/L - Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });
        alert("✅ Teacher Registered Successfully!");
      }
    });
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '20px' }}>
        <h2>🧑‍🏫 Manage Teachers</h2>
        <button onClick={() => setShowForm(true)} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>+ Add New Teacher</button>
      </div>

      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '12px', width: '450px' }}>
            <h3>Add New Teacher</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <input type="text" placeholder="Teacher Full Name" value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              <select value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} style={inputStyle}>
                <option value="O/L - Mathematics">O/L - Mathematics</option>
                <option value="O/L - Science">O/L - Science</option>
                <option value="O/L - Sinhala">O/L - Sinhala</option>
                <option value="O/L - English">O/L - English</option>
                <option value="A/L - Business Studies">A/L - Business Studies</option>
                <option value="A/L - Accounting">A/L - Accounting</option>
                <option value="A/L - Physics">A/L - Physics</option>
              </select>
              <input type="text" placeholder="Qualifications (Optional)" value={formData.qualifications} onChange={(e) => setFormData({...formData, qualifications: e.target.value})} style={inputStyle} />
              <input type="text" placeholder="Contact Number" value={formData.phone_number} onChange={(e) => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              <input type="text" placeholder="Address" value={formData.address} onChange={(e) => setFormData({...formData, address: e.target.value})} style={inputStyle} />
              <div style={{ display: 'flex', gap: '10px' }}>
                <button type="button" onClick={() => setShowForm(false)} style={{ flex: 1, padding: '10px', backgroundColor: '#cbd5e1', border: 'none', borderRadius: '8px' }}>Cancel</button>
                <button type="submit" style={{ flex: 1, padding: '10px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px' }}>Save</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
        <thead style={{ backgroundColor: '#15803d', color: 'white' }}>
          <tr><th style={thStyle}>Full Name</th><th style={thStyle}>Teaching Subject</th><th style={thStyle}>Qualifications</th><th style={thStyle}>Phone</th><th style={thStyle}>Address</th></tr>
        </thead>
        <tbody>
          {teachers.map(t => (
            <tr key={t.id} style={{ borderBottom: '1px solid #e2e8f0' }}><td style={tdStyle}><b>{t.name}</b></td><td style={tdStyle}><span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '6px', fontSize: '13px', fontWeight: 'bold' }}>{t.subject}</span></td><td style={tdStyle}>{t.qualifications || '-'}</td><td style={tdStyle}>{t.phone_number}</td><td style={tdStyle}>{t.address || '-'}</td></tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
const inputStyle = { padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1' };
const thStyle = { padding: '12px', textAlign: 'left' };
const tdStyle = { padding: '12px' };
